int[] next = new int[maxNodes * 26];
bool[] end = new bool[maxNodes];
int count = 1;                                       // node 0 is the root

void Insert(string w) {
    int v = 0;
    foreach (char ch in w) {
        int c = ch - 'a';
        if (next[v * 26 + c] == 0) next[v * 26 + c] = count++;   // 0 means no edge
        v = next[v * 26 + c];
    }
    end[v] = true;
}

int Find(string s) {                                 // -1: no such path
    int v = 0;
    foreach (char ch in s) {
        v = next[v * 26 + (ch - 'a')];
        if (v == 0) return -1;
    }
    return v;
}

